INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('art', 1, 'Quelle couleur obtient-on en mélangeant du bleu et du jaune ?', 'Vert', ARRAY['Orange', 'Violet', 'Marron'], 'fr', true, 'Le bleu et le jaune sont des couleurs primaires qui donnent du vert lorsqu''on les mélange.'),
('art', 1, 'Quelles sont les trois couleurs primaires en peinture ?', 'Rouge, bleu, jaune', ARRAY['Rouge, vert, bleu', 'Orange, violet, vert', 'Noir, blanc, rouge'], 'fr', true, 'En peinture, les trois couleurs primaires sont le rouge, le bleu et le jaune. On peut créer toutes les autres couleurs à partir de celles-ci.'),
('art', 1, 'Quel outil utilise un peintre pour mélanger ses couleurs ?', 'Une palette', ARRAY['Un chevalet', 'Un cadre', 'Une toile'], 'fr', true, 'La palette est une surface plate sur laquelle le peintre dépose et mélange ses couleurs.'),
('art', 1, 'Comment appelle-t-on un tableau représentant un paysage de mer ?', 'Une marine', ARRAY['Un portrait', 'Une nature morte', 'Une fresque'], 'fr', true, 'Une marine est un genre pictural représentant la mer, les bateaux ou les côtes.'),
('art', 1, 'Quel est le support le plus courant pour peindre un tableau ?', 'La toile', ARRAY['Le papier', 'Le bois', 'Le verre'], 'fr', true, 'La toile, généralement en lin ou en coton, est le support le plus utilisé par les peintres depuis la Renaissance.'),
('art', 1, 'Comment appelle-t-on une peinture représentant des fruits et des objets ?', 'Une nature morte', ARRAY['Un portrait', 'Un paysage', 'Une fresque'], 'fr', true, 'La nature morte est un genre artistique représentant des objets inanimés comme des fruits, des fleurs ou des ustensiles.'),
('art', 1, 'Quel monument parisien est une pyramide de verre ?', 'La Pyramide du Louvre', ARRAY['La Tour Eiffel', 'L''Arc de Triomphe', 'Le Sacré-Cœur'], 'fr', true, 'La Pyramide du Louvre, conçue par l''architecte I.M. Pei, a été inaugurée en 1989 dans la cour du musée du Louvre.'),
('art', 1, 'Quelle couleur obtient-on en mélangeant du rouge et du blanc ?', 'Rose', ARRAY['Orange', 'Violet', 'Beige'], 'fr', true, 'En ajoutant du blanc au rouge, on obtient du rose, une version éclaircie du rouge.'),
('art', 1, 'Comment appelle-t-on une peinture réalisée directement sur un mur ?', 'Une fresque', ARRAY['Un tableau', 'Une gravure', 'Une aquarelle'], 'fr', true, 'La fresque est une technique de peinture murale où les pigments sont appliqués sur un enduit frais.'),
('art', 1, 'Quel est le musée le plus visité au monde ?', 'Le Louvre', ARRAY['Le British Museum', 'Le Metropolitan Museum', 'Le Musée d''Orsay'], 'fr', true, 'Le musée du Louvre à Paris accueille environ 10 millions de visiteurs par an, ce qui en fait le musée le plus visité au monde.'),
('art', 1, 'Quelle couleur obtient-on en mélangeant du rouge et du bleu ?', 'Violet', ARRAY['Vert', 'Orange', 'Marron'], 'fr', true, 'Le rouge et le bleu sont des couleurs primaires dont le mélange produit du violet.'),
('art', 1, 'Quel artiste italien a peint la fresque de la Cène ?', 'Léonard de Vinci', ARRAY['Michel-Ange', 'Raphaël', 'Botticelli'], 'fr', true, 'La Cène a été peinte par Léonard de Vinci entre 1495 et 1498 dans le réfectoire du couvent Santa Maria delle Grazie à Milan.'),
('art', 1, 'Comment appelle-t-on un dessin rapide fait à main levée ?', 'Un croquis', ARRAY['Une gravure', 'Une lithographie', 'Un vitrail'], 'fr', true, 'Un croquis est un dessin rapide réalisé à main levée pour saisir l''essentiel d''un sujet.'),
('art', 1, 'Quel est le nom de la statue géante qui se trouve à New York ?', 'La Statue de la Liberté', ARRAY['Le Penseur', 'Le David', 'Le Colosse de Rhodes'], 'fr', true, 'La Statue de la Liberté a été offerte par la France aux États-Unis en 1886 et conçue par le sculpteur Bartholdi.'),
('art', 1, 'Quel matériau utilise-t-on souvent pour faire des sculptures blanches ?', 'Le marbre', ARRAY['Le bronze', 'L''argile', 'Le bois'], 'fr', true, 'Le marbre blanc est un matériau noble utilisé depuis l''Antiquité pour la sculpture, notamment par les Grecs et les Romains.'),
('art', 1, 'Quelle couleur obtient-on en mélangeant du rouge et du jaune ?', 'Orange', ARRAY['Vert', 'Violet', 'Marron'], 'fr', true, 'Le mélange de rouge et de jaune, deux couleurs primaires, donne de l''orange.'),
('art', 1, 'Comment appelle-t-on un tableau représentant le visage d''une personne ?', 'Un portrait', ARRAY['Un paysage', 'Une nature morte', 'Une marine'], 'fr', true, 'Le portrait est un genre artistique visant à représenter l''apparence d''une personne, en se concentrant sur son visage.'),
('art', 1, 'Quel célèbre bâtiment blanc se trouve à Sydney ?', 'L''Opéra de Sydney', ARRAY['Le Taj Mahal', 'La Maison Blanche', 'Le Colisée'], 'fr', true, 'L''Opéra de Sydney, conçu par l''architecte Jørn Utzon, est célèbre pour ses voiles blanches caractéristiques.'),
('art', 1, 'Quelle est la technique de peinture qui utilise de l''eau ?', 'L''aquarelle', ARRAY['La peinture à l''huile', 'L''acrylique', 'La gouache'], 'fr', true, 'L''aquarelle est une technique de peinture utilisant des pigments dilués dans l''eau, produisant des effets de transparence.'),
('art', 1, 'Comment appelle-t-on le support sur lequel on pose la toile pour peindre ?', 'Un chevalet', ARRAY['Une palette', 'Un cadre', 'Un pupitre'], 'fr', true, 'Le chevalet est un trépied en bois ou métal servant à maintenir la toile pendant que l''artiste peint.'),
('art', 1, 'Quel artiste est connu pour avoir peint des nénuphars ?', 'Claude Monet', ARRAY['Pierre-Auguste Renoir', 'Edgar Degas', 'Paul Cézanne'], 'fr', true, 'Claude Monet a peint environ 250 tableaux de nénuphars dans son jardin de Giverny.'),
('art', 1, 'De quelle couleur est le ciel dans la plupart des peintures de paysages ?', 'Bleu', ARRAY['Vert', 'Rouge', 'Jaune'], 'fr', true, 'Le ciel est traditionnellement peint en bleu, bien que les artistes jouent souvent avec différentes teintes selon l''heure du jour.'),
('art', 1, 'Quel musée parisien était autrefois une gare ?', 'Le Musée d''Orsay', ARRAY['Le Louvre', 'Le Centre Pompidou', 'Le Grand Palais'], 'fr', true, 'Le Musée d''Orsay occupe l''ancienne gare d''Orsay, construite en 1900 et transformée en musée en 1986.'),
('art', 1, 'Quel artiste a peint des tableaux de danseuses de ballet ?', 'Edgar Degas', ARRAY['Claude Monet', 'Paul Cézanne', 'Édouard Manet'], 'fr', true, 'Edgar Degas est célèbre pour ses peintures et pastels représentant des danseuses de l''Opéra de Paris.'),
('art', 1, 'Comment appelle-t-on l''art de découper et coller du papier ?', 'Le collage', ARRAY['La gravure', 'La sculpture', 'Le moulage'], 'fr', true, 'Le collage est une technique artistique consistant à assembler des morceaux de papier, tissu ou autres matériaux sur un support.'),
('art', 1, 'Quelle est la couleur complémentaire du rouge ?', 'Vert', ARRAY['Bleu', 'Jaune', 'Orange'], 'fr', true, 'Sur le cercle chromatique, le vert est la couleur complémentaire du rouge, c''est-à-dire celle qui lui est directement opposée.'),
('art', 1, 'Quel artiste espagnol a peint des visages cubistes ?', 'Pablo Picasso', ARRAY['Salvador Dalí', 'Joan Miró', 'Francisco Goya'], 'fr', true, 'Pablo Picasso a cofondé le cubisme, mouvement qui représente les sujets sous des formes géométriques fragmentées.'),
('art', 1, 'Comment appelle-t-on une œuvre d''art faite avec de petits morceaux de verre ou pierre ?', 'Une mosaïque', ARRAY['Un vitrail', 'Une fresque', 'Une tapisserie'], 'fr', true, 'La mosaïque est un art décoratif composé de petits fragments colorés assemblés pour former un motif ou une image.'),
('art', 1, 'Quel pays est connu pour ses estampes traditionnelles en bois ?', 'Le Japon', ARRAY['La Chine', 'L''Inde', 'La Corée'], 'fr', true, 'Le Japon est célèbre pour ses estampes ukiyo-e, gravures sur bois représentant des paysages, des acteurs et des courtisanes.'),
('art', 1, 'Quelle matière utilise-t-on pour mouler des statues en métal ?', 'Le bronze', ARRAY['L''or', 'L''argent', 'Le fer'], 'fr', true, 'Le bronze est un alliage de cuivre et d''étain très utilisé en sculpture depuis l''Antiquité pour sa résistance et sa malléabilité.'),
('art', 1, 'Quel est le nom du célèbre musée de Madrid ?', 'Le Prado', ARRAY['Le Louvre', 'Les Offices', 'L''Ermitage'], 'fr', true, 'Le musée du Prado à Madrid abrite l''une des plus importantes collections d''art européen du XIIe au XIXe siècle.'),
('art', 1, 'De quelle couleur sont les tournesols peints par Van Gogh ?', 'Jaunes', ARRAY['Rouges', 'Bleus', 'Blancs'], 'fr', true, 'Les célèbres Tournesols de Van Gogh sont représentés dans différentes nuances de jaune.'),
('art', 1, 'Comment appelle-t-on une fenêtre en verre coloré dans une église ?', 'Un vitrail', ARRAY['Une fresque', 'Une mosaïque', 'Un relief'], 'fr', true, 'Le vitrail est une composition de pièces de verre coloré assemblées avec du plomb, typique de l''architecture des cathédrales.'),
('art', 1, 'Quel type d''art peut-on voir dans les grottes de Lascaux ?', 'L''art rupestre', ARRAY['La sculpture grecque', 'La mosaïque romaine', 'L''art gothique'], 'fr', true, 'Les grottes de Lascaux contiennent des peintures rupestres datant d''environ 17 000 ans, représentant des animaux et des scènes de chasse.'),
('art', 1, 'Qui a conçu la Tour Eiffel ?', 'Gustave Eiffel', ARRAY['Le Corbusier', 'Haussmann', 'Auguste Bartholdi'], 'fr', true, 'La Tour Eiffel a été conçue par Gustave Eiffel et construite pour l''Exposition universelle de 1889 à Paris.'),
('art', 1, 'Quelle est la forme d''art qui utilise l''argile ?', 'La poterie', ARRAY['La gravure', 'La lithographie', 'Le tissage'], 'fr', true, 'La poterie est l''art de fabriquer des objets en argile modelée puis cuite au four.'),
('art', 1, 'Quel artiste a peint des boîtes de soupe Campbell ?', 'Andy Warhol', ARRAY['Roy Lichtenstein', 'Keith Haring', 'Jean-Michel Basquiat'], 'fr', true, 'Andy Warhol a créé sa célèbre série de 32 toiles de boîtes de soupe Campbell en 1962, devenant une icône du Pop Art.'),
('art', 1, 'Comment appelle-t-on une statue représentant une personne ?', 'Une sculpture', ARRAY['Un tableau', 'Un dessin', 'Une gravure'], 'fr', true, 'La sculpture est l''art de modeler ou de tailler une matière pour créer une forme en trois dimensions.'),
('art', 1, 'Quel crayon utilise-t-on pour dessiner en noir et blanc ?', 'Le crayon graphite', ARRAY['Le crayon de couleur', 'Le pastel', 'Le fusain'], 'fr', true, 'Le crayon graphite, communément appelé crayon à papier, est l''outil de base pour le dessin en noir et blanc.'),
('art', 1, 'Dans quel pays se trouve la cathédrale de la Sagrada Familia ?', 'L''Espagne', ARRAY['L''Italie', 'Le Portugal', 'La France'], 'fr', true, 'La Sagrada Familia est une basilique conçue par l''architecte Antoni Gaudí à Barcelone, en Espagne.'),
('art', 1, 'Quel peintre français est connu pour ses peintures de la vie parisienne ?', 'Henri de Toulouse-Lautrec', ARRAY['Claude Monet', 'Paul Cézanne', 'Gustave Courbet'], 'fr', true, 'Toulouse-Lautrec est célèbre pour ses affiches et peintures représentant la vie nocturne de Montmartre à Paris.'),
('art', 1, 'Comment appelle-t-on une image imprimée à partir d''une plaque gravée ?', 'Une gravure', ARRAY['Une aquarelle', 'Un pastel', 'Un lavis'], 'fr', true, 'La gravure est une technique d''impression où l''image est creusée ou incisée dans une plaque de métal, de bois ou de pierre.'),
('art', 1, 'De quel pays est originaire l''art de l''origami ?', 'Le Japon', ARRAY['La Chine', 'La Corée', 'L''Inde'], 'fr', true, 'L''origami est l''art traditionnel japonais du pliage de papier pour créer des formes décoratives.'),
('art', 1, 'Quel est le nom du célèbre musée d''art moderne à Paris ?', 'Le Centre Pompidou', ARRAY['Le Louvre', 'Le Musée d''Orsay', 'Le Petit Palais'], 'fr', true, 'Le Centre Pompidou, aussi appelé Beaubourg, est un musée d''art moderne et contemporain inauguré en 1977 à Paris.'),
('art', 1, 'Quelle couleur symbolise souvent la nature et l''espoir ?', 'Le vert', ARRAY['Le rouge', 'Le bleu', 'Le jaune'], 'fr', true, 'Le vert est universellement associé à la nature, à la croissance et à l''espoir.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('art', 2, 'Quel peintre impressionniste a peint la série des cathédrales de Rouen ?', 'Claude Monet', ARRAY['Camille Pissarro', 'Alfred Sisley', 'Pierre-Auguste Renoir'], 'fr', true, 'Monet a peint plus de 30 vues de la cathédrale de Rouen entre 1892 et 1894, capturant les variations de lumière.'),
('art', 2, 'Quel architecte a conçu la chapelle Notre-Dame-du-Haut à Ronchamp ?', 'Le Corbusier', ARRAY['Frank Lloyd Wright', 'Oscar Niemeyer', 'Tadao Ando'], 'fr', true, 'Le Corbusier a conçu cette chapelle en béton inaugurée en 1955, chef-d''œuvre de l''architecture moderne.'),
('art', 2, 'Quel mouvement artistique est associé à Henri Matisse ?', 'Le Fauvisme', ARRAY['L''Impressionnisme', 'Le Cubisme', 'L''Expressionnisme'], 'fr', true, 'Henri Matisse est considéré comme le chef de file du Fauvisme, mouvement caractérisé par des couleurs vives et audacieuses.'),
('art', 2, 'Comment appelle-t-on la technique de peinture utilisant des pigments mélangés à l''œuf ?', 'La tempera', ARRAY['L''aquarelle', 'La gouache', 'L''encaustique'], 'fr', true, 'La tempera utilise le jaune d''œuf comme liant pour les pigments. C''est une technique très utilisée avant l''invention de la peinture à l''huile.'),
('art', 2, 'Quel peintre est connu pour son tableau "Le Bal du moulin de la Galette" ?', 'Pierre-Auguste Renoir', ARRAY['Édouard Manet', 'Claude Monet', 'Edgar Degas'], 'fr', true, 'Renoir a peint cette scène de bal en plein air à Montmartre en 1876, chef-d''œuvre de l''impressionnisme.'),
('art', 2, 'Quel style architectural est caractérisé par des arcs brisés et des vitraux ?', 'Le gothique', ARRAY['Le roman', 'Le baroque', 'Le classique'], 'fr', true, 'L''architecture gothique se distingue par ses arcs brisés, ses voûtes sur croisée d''ogives et ses grands vitraux.'),
('art', 2, 'Qui a peint "Les Tournesols", une série de natures mortes célèbres ?', 'Vincent van Gogh', ARRAY['Paul Gauguin', 'Claude Monet', 'Paul Cézanne'], 'fr', true, 'Van Gogh a peint plusieurs versions de tournesols entre 1888 et 1889, principalement à Arles.'),
('art', 2, 'Quel est le nom du courant artistique qui utilise des points de couleur juxtaposés ?', 'Le Pointillisme', ARRAY['L''Impressionnisme', 'Le Divisionnisme', 'Le Fauvisme'], 'fr', true, 'Le pointillisme, développé par Seurat et Signac, consiste à juxtaposer de petits points de couleur pure pour créer une image.'),
('art', 2, 'Quel sculpteur français a créé "Les Bourgeois de Calais" ?', 'Auguste Rodin', ARRAY['Camille Claudel', 'Antoine Bourdelle', 'Aristide Maillol'], 'fr', true, 'Auguste Rodin a réalisé ce groupe sculptural entre 1884 et 1889, commémorant un épisode de la Guerre de Cent Ans.'),
('art', 2, 'Quel artiste pop art est connu pour ses bandes dessinées agrandies ?', 'Roy Lichtenstein', ARRAY['Andy Warhol', 'Jasper Johns', 'Robert Rauschenberg'], 'fr', true, 'Roy Lichtenstein a repris le style des comics américains en agrandissant des vignettes de BD avec des points Ben-Day.'),
('art', 2, 'Quel musée londonien abrite la collection d''art moderne Tate ?', 'La Tate Modern', ARRAY['Le British Museum', 'La National Gallery', 'Le Victoria and Albert Museum'], 'fr', true, 'La Tate Modern, installée dans une ancienne centrale électrique, est le musée d''art moderne le plus visité au monde.'),
('art', 2, 'Quel artiste est à l''origine du mouvement artistique De Stijl ?', 'Piet Mondrian', ARRAY['Vassily Kandinsky', 'Kasimir Malevitch', 'Paul Klee'], 'fr', true, 'Mondrian est le principal représentant de De Stijl, mouvement né aux Pays-Bas en 1917 prônant l''abstraction géométrique.'),
('art', 2, 'Comment appelle-t-on la représentation d''une scène biblique dans l''art ?', 'Un art sacré', ARRAY['Un art profane', 'Un art païen', 'Un art laïc'], 'fr', true, 'L''art sacré désigne les œuvres représentant des scènes religieuses, très présentes dans l''histoire de la peinture occidentale.'),
('art', 2, 'Quel peintre hollandais est connu pour ses scènes de genre intimes ?', 'Johannes Vermeer', ARRAY['Rembrandt', 'Frans Hals', 'Jan Steen'], 'fr', true, 'Vermeer est célèbre pour ses scènes d''intérieur baignées de lumière douce, comme "La Laitière" ou "La Jeune Fille à la perle".'),
('art', 2, 'Quel artiste a réalisé la sculpture "La Vénus de Milo" ?', 'Alexandros d''Antioche', ARRAY['Phidias', 'Praxitèle', 'Polyclète'], 'fr', true, 'La Vénus de Milo, sculptée vers 100 av. J.-C., est attribuée à Alexandros d''Antioche et se trouve au musée du Louvre.'),
('art', 2, 'Quel courant artistique est né en Italie au XVe siècle ?', 'La Renaissance', ARRAY['Le Baroque', 'Le Maniérisme', 'Le Gothique'], 'fr', true, 'La Renaissance est née à Florence au XVe siècle, marquant un renouveau artistique et intellectuel en Europe.'),
('art', 2, 'Quel peintre est connu pour ses tableaux de la montagne Sainte-Victoire ?', 'Paul Cézanne', ARRAY['Claude Monet', 'Camille Pissarro', 'Alfred Sisley'], 'fr', true, 'Paul Cézanne a peint plus de 80 fois la montagne Sainte-Victoire en Provence, symbole de son attachement à cette région.'),
('art', 2, 'Quel artiste belge a peint "La Trahison des images" avec une pipe ?', 'René Magritte', ARRAY['Paul Delvaux', 'James Ensor', 'Fernand Khnopff'], 'fr', true, 'Magritte a peint ce tableau surréaliste en 1929, avec l''inscription "Ceci n''est pas une pipe" sous l''image d''une pipe.'),
('art', 2, 'Quel est le style architectural du château de Versailles ?', 'Le classicisme', ARRAY['Le baroque', 'Le gothique', 'Le roman'], 'fr', true, 'Le château de Versailles est un chef-d''œuvre de l''architecture classique française du XVIIe siècle.'),
('art', 2, 'Quel peintre a réalisé "Impression, soleil levant" ?', 'Claude Monet', ARRAY['Édouard Manet', 'Pierre-Auguste Renoir', 'Camille Pissarro'], 'fr', true, 'Ce tableau de 1872 a donné son nom au mouvement impressionniste lors de l''exposition de 1874.'),
('art', 2, 'Quel artiste est connu pour ses sérigraphies de Marilyn Monroe ?', 'Andy Warhol', ARRAY['Roy Lichtenstein', 'Keith Haring', 'Jean-Michel Basquiat'], 'fr', true, 'Andy Warhol a créé sa célèbre série de sérigraphies de Marilyn Monroe en 1962, après la mort de l''actrice.'),
('art', 2, 'Comment appelle-t-on un art décoratif fait de fils entrelacés ?', 'La tapisserie', ARRAY['La mosaïque', 'Le vitrail', 'La céramique'], 'fr', true, 'La tapisserie est un art textile où des fils de couleur sont tissés pour créer des motifs et des scènes.'),
('art', 2, 'Quel peintre romantique allemand a peint "Le Voyageur contemplant une mer de nuages" ?', 'Caspar David Friedrich', ARRAY['Philipp Otto Runge', 'Carl Spitzweg', 'Arnold Böcklin'], 'fr', true, 'Friedrich a peint cette toile emblématique du romantisme vers 1818, montrant un homme face à la nature sublime.'),
('art', 2, 'Quel artiste mexicaine est connue pour ses autoportraits colorés ?', 'Frida Kahlo', ARRAY['Diego Rivera', 'Remedios Varo', 'Leonora Carrington'], 'fr', true, 'Frida Kahlo a peint plus de 55 autoportraits exprimant sa douleur physique et émotionnelle avec un style unique.'),
('art', 2, 'Quel monument indien en marbre blanc est considéré comme un chef-d''œuvre architectural ?', 'Le Taj Mahal', ARRAY['Le Fort Rouge', 'Le Lotus Temple', 'Le Palais des Vents'], 'fr', true, 'Le Taj Mahal à Agra, construit au XVIIe siècle, est un mausolée en marbre blanc édifié par l''empereur Shah Jahan.'),
('art', 2, 'Quel peintre a fondé le mouvement du Suprématisme ?', 'Kasimir Malevitch', ARRAY['Vassily Kandinsky', 'El Lissitzky', 'Alexandre Rodtchenko'], 'fr', true, 'Malevitch a fondé le Suprématisme en 1915, un mouvement d''art abstrait basé sur des formes géométriques simples.'),
('art', 2, 'Comment s''appelle la technique de peinture sur céramique recouverte d''émail ?', 'La faïence', ARRAY['La porcelaine', 'Le grès', 'La terre cuite'], 'fr', true, 'La faïence est une technique de céramique recouverte d''un émail opaque à base d''étain, permettant un décor peint.'),
('art', 2, 'Quel artiste a créé les sculptures de "Nanas" colorées ?', 'Niki de Saint Phalle', ARRAY['Louise Bourgeois', 'Yayoi Kusama', 'Barbara Hepworth'], 'fr', true, 'Niki de Saint Phalle est célèbre pour ses Nanas, sculptures féminines monumentales et colorées créées dans les années 1960.'),
('art', 2, 'Quel peintre américain est connu pour son tableau "Nighthawks" ?', 'Edward Hopper', ARRAY['Norman Rockwell', 'Grant Wood', 'Andrew Wyeth'], 'fr', true, 'Edward Hopper a peint Nighthawks en 1942, représentant des clients dans un diner la nuit, symbole de solitude urbaine.'),
('art', 2, 'Quel est le style architectural du Panthéon de Rome ?', 'L''architecture romaine', ARRAY['L''architecture grecque', 'L''architecture gothique', 'L''architecture baroque'], 'fr', true, 'Le Panthéon de Rome, construit sous Hadrien vers 125, est un chef-d''œuvre d''architecture romaine avec sa coupole monumentale.'),
('art', 2, 'Quel peintre postimpressionniste a vécu à Tahiti ?', 'Paul Gauguin', ARRAY['Paul Cézanne', 'Henri de Toulouse-Lautrec', 'Georges Seurat'], 'fr', true, 'Paul Gauguin a quitté la France pour Tahiti en 1891, cherchant l''inspiration dans les paysages et la culture polynésienne.'),
('art', 2, 'Quelle est la technique de dessin au bâton de charbon ?', 'Le fusain', ARRAY['Le pastel', 'La sanguine', 'Le graphite'], 'fr', true, 'Le fusain est un bâton de charbon de bois utilisé pour dessiner, offrant des noirs profonds et veloutés.'),
('art', 2, 'Quel artiste français a peint des scènes de la vie tahitienne ?', 'Paul Gauguin', ARRAY['Henri Matisse', 'Paul Signac', 'Odilon Redon'], 'fr', true, 'Gauguin a vécu à Tahiti et en a peint de nombreuses scènes aux couleurs vives et aux sujets exotiques.'),
('art', 2, 'Quel artiste de rue britannique est connu pour ses pochoirs engagés ?', 'Banksy', ARRAY['Shepard Fairey', 'JR', 'Invader'], 'fr', true, 'Banksy est un artiste de street art dont l''identité reste secrète, connu pour ses œuvres satiriques au pochoir.'),
('art', 2, 'Quel artiste italien de la Renaissance a peint "L''École d''Athènes" ?', 'Raphaël', ARRAY['Léonard de Vinci', 'Michel-Ange', 'Le Titien'], 'fr', true, 'Raphaël a peint cette fresque monumentale entre 1509 et 1511 dans les chambres du Vatican.'),
('art', 2, 'Comment appelle-t-on l''art de créer des images avec des fils brodés ?', 'La broderie', ARRAY['La tapisserie', 'Le tissage', 'Le tricot'], 'fr', true, 'La broderie est une technique de décoration textile consistant à orner un tissu de motifs réalisés à l''aiguille et au fil.'),
('art', 2, 'Quel artiste est connu pour ses installations de points colorés "Infinity Rooms" ?', 'Yayoi Kusama', ARRAY['Marina Abramovic', 'Ai Weiwei', 'Olafur Eliasson'], 'fr', true, 'Yayoi Kusama est une artiste japonaise célèbre pour ses Infinity Rooms, espaces immersifs remplis de pois et de miroirs.'),
('art', 2, 'Quel est le plus grand musée d''art au monde par sa surface ?', 'Le Louvre', ARRAY['L''Ermitage', 'Le Metropolitan Museum', 'Le British Museum'], 'fr', true, 'Le musée du Louvre à Paris, avec 72 735 m² d''espace d''exposition, est le plus grand musée d''art au monde.'),
('art', 2, 'Quel peintre espagnol a créé "Les Ménines" ?', 'Diego Velázquez', ARRAY['Francisco Goya', 'El Greco', 'Bartolomé Murillo'], 'fr', true, 'Velázquez a peint Les Ménines en 1656, un chef-d''œuvre complexe montrant l''infante Marguerite entourée de sa cour.'),
('art', 2, 'Quel mouvement artistique cherche à représenter les rêves et l''inconscient ?', 'Le Surréalisme', ARRAY['L''Expressionnisme', 'Le Dadaïsme', 'Le Symbolisme'], 'fr', true, 'Le Surréalisme, fondé par André Breton en 1924, explore le monde des rêves et de l''inconscient dans l''art.'),
('art', 2, 'Quel architecte catalan a conçu le parc Güell à Barcelone ?', 'Antoni Gaudí', ARRAY['Le Corbusier', 'Oscar Niemeyer', 'Santiago Calatrava'], 'fr', true, 'Antoni Gaudí a conçu le parc Güell entre 1900 et 1914, un jardin public rempli de mosaïques et de formes organiques.'),
('art', 2, 'Quel peintre néerlandais a vécu à Arles et s''est coupé l''oreille ?', 'Vincent van Gogh', ARRAY['Paul Gauguin', 'Rembrandt', 'Jan Vermeer'], 'fr', true, 'Van Gogh s''est installé à Arles en 1888 et s''est coupé une partie de l''oreille après une dispute avec Paul Gauguin.'),
('art', 2, 'Quel type de peinture utilise des pigments mélangés à de l''huile ?', 'La peinture à l''huile', ARRAY['L''aquarelle', 'La gouache', 'L''acrylique'], 'fr', true, 'La peinture à l''huile utilise des pigments broyés dans une huile siccative, permettant des effets de profondeur et de brillance.'),
('art', 2, 'Quel artiste a peint le tableau "Le Déjeuner des canotiers" ?', 'Pierre-Auguste Renoir', ARRAY['Claude Monet', 'Édouard Manet', 'Gustave Caillebotte'], 'fr', true, 'Renoir a peint cette scène joyeuse de déjeuner en plein air en 1881, un sommet de l''impressionnisme.'),
('art', 2, 'Comment appelle-t-on les peintures préhistoriques trouvées dans des grottes ?', 'L''art pariétal', ARRAY['L''art rupestre', 'L''art primitif', 'L''art brut'], 'fr', true, 'L''art pariétal désigne les peintures et gravures réalisées sur les parois des grottes par les hommes préhistoriques.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('art', 3, 'Quel peintre a réalisé le tableau "Le Sacre de Napoléon" ?', 'Jacques-Louis David', ARRAY['Théodore Géricault', 'Eugène Delacroix', 'Antoine-Jean Gros'], 'fr', true, 'David a peint cette immense toile de 10 mètres entre 1805 et 1807, représentant le couronnement de Napoléon Ier.'),
('art', 3, 'Quel artiste est le principal représentant du mouvement Dada à New York ?', 'Marcel Duchamp', ARRAY['Man Ray', 'Francis Picabia', 'Morton Schamberg'], 'fr', true, 'Marcel Duchamp a introduit le mouvement Dada à New York avec ses ready-mades, révolutionnant le concept même de l''art.'),
('art', 3, 'Comment appelle-t-on la technique de gravure sur cuivre utilisant de l''acide ?', 'L''eau-forte', ARRAY['La lithographie', 'La xylographie', 'La sérigraphie'], 'fr', true, 'L''eau-forte est une technique de gravure en creux où l''acide mord le cuivre dans les zones non protégées par un vernis.'),
('art', 3, 'Quel peintre italien du Quattrocento a peint "L''Annonciation" du musée des Offices ?', 'Fra Angelico', ARRAY['Fra Filippo Lippi', 'Masaccio', 'Paolo Uccello'], 'fr', true, 'Fra Angelico a peint cette Annonciation vers 1426, chef-d''œuvre de la Renaissance italienne primitive.'),
('art', 3, 'Quel mouvement artistique a été lancé par Filippo Tommaso Marinetti en 1909 ?', 'Le Futurisme', ARRAY['Le Dadaïsme', 'Le Constructivisme', 'Le Vorticisme'], 'fr', true, 'Marinetti a publié le Manifeste du Futurisme en 1909, exaltant la vitesse, la technologie et la modernité.'),
('art', 3, 'Quel artiste a créé "Le Grand Bleu" et est associé au Nouveau Réalisme ?', 'Yves Klein', ARRAY['Arman', 'Jean Tinguely', 'Daniel Spoerri'], 'fr', true, 'Yves Klein est célèbre pour son bleu breveté (IKB) et ses monochromes, pilier du Nouveau Réalisme français.'),
('art', 3, 'Quel architecte a conçu le musée Guggenheim de Bilbao ?', 'Frank Gehry', ARRAY['Zaha Hadid', 'Renzo Piano', 'Norman Foster'], 'fr', true, 'Frank Gehry a conçu ce musée aux formes organiques recouvertes de titane, inauguré en 1997 à Bilbao.'),
('art', 3, 'Quel peintre hollandais du XVIIe siècle est connu pour sa "Leçon d''anatomie" ?', 'Rembrandt', ARRAY['Frans Hals', 'Johannes Vermeer', 'Jan Steen'], 'fr', true, 'Rembrandt a peint "La Leçon d''anatomie du docteur Tulp" en 1632, un portrait de groupe novateur.'),
('art', 3, 'Quel est le style de la basilique du Sacré-Cœur à Paris ?', 'Romano-byzantin', ARRAY['Gothique', 'Baroque', 'Art nouveau'], 'fr', true, 'Le Sacré-Cœur, achevé en 1914, est de style romano-byzantin avec sa coupole blanche caractéristique.'),
('art', 3, 'Quel peintre a réalisé "L''Homme au turban rouge", considéré comme un des premiers autoportraits ?', 'Jan van Eyck', ARRAY['Rogier van der Weyden', 'Hans Memling', 'Robert Campin'], 'fr', true, 'Jan van Eyck a peint ce tableau en 1433, considéré comme un de ses possibles autoportraits.'),
('art', 3, 'Quel mouvement artistique est caractérisé par l''utilisation de formes géométriques simples ?', 'Le Minimalisme', ARRAY['Le Constructivisme', 'L''Art concret', 'Le Suprématisme'], 'fr', true, 'Le Minimalisme, apparu dans les années 1960, réduit l''art à ses formes les plus essentielles et géométriques.'),
('art', 3, 'Quel artiste japonais est connu pour son estampe "La Grande Vague de Kanagawa" ?', 'Hokusai', ARRAY['Hiroshige', 'Utamaro', 'Sharaku'], 'fr', true, 'Hokusai a créé cette célèbre estampe vers 1831, faisant partie de la série "Trente-six vues du mont Fuji".'),
('art', 3, 'Quel sculpteur roumain a créé "La Colonne sans fin" ?', 'Constantin Brâncuși', ARRAY['Alberto Giacometti', 'Alexander Calder', 'Jean Arp'], 'fr', true, 'Brâncuși a réalisé La Colonne sans fin en 1938 à Târgu Jiu en Roumanie, une sculpture de près de 30 mètres.'),
('art', 3, 'Quel artiste américain est connu pour ses peintures de drapeaux américains ?', 'Jasper Johns', ARRAY['Robert Rauschenberg', 'Andy Warhol', 'Roy Lichtenstein'], 'fr', true, 'Jasper Johns a peint son premier Flag en 1954-1955, brouillant les frontières entre art et objet.'),
('art', 3, 'Quel est le nom du style architectural caractérisé par des courbes et des motifs végétaux ?', 'L''Art nouveau', ARRAY['L''Art déco', 'Le Jugendstil', 'Le Modern Style'], 'fr', true, 'L''Art nouveau, apparu vers 1890, se caractérise par des lignes courbes inspirées de la nature et des ornements végétaux.'),
('art', 3, 'Quel peintre a réalisé le triptyque "Le Jardin des délices" ?', 'Jérôme Bosch', ARRAY['Pieter Bruegel l''Ancien', 'Hans Memling', 'Rogier van der Weyden'], 'fr', true, 'Jérôme Bosch a peint ce triptyque fantastique vers 1500-1505, montrant le paradis, la Terre et l''enfer.'),
('art', 3, 'Quel artiste a emballé le Pont-Neuf à Paris ?', 'Christo', ARRAY['Daniel Buren', 'JR', 'Jeff Koons'], 'fr', true, 'Christo et Jeanne-Claude ont emballé le Pont-Neuf en 1985 avec du tissu doré, une œuvre d''art éphémère spectaculaire.'),
('art', 3, 'Quel est le procédé de peinture qui consiste à appliquer de la cire chaude ?', 'L''encaustique', ARRAY['La tempera', 'La fresque', 'La détrempe'], 'fr', true, 'L''encaustique est une technique antique utilisant des pigments mélangés à de la cire d''abeille fondue.'),
('art', 3, 'Quel peintre préraphaélite a peint "Ophélie" noyée dans une rivière ?', 'John Everett Millais', ARRAY['Dante Gabriel Rossetti', 'William Holman Hunt', 'Edward Burne-Jones'], 'fr', true, 'Millais a peint Ophélie en 1851-1852, représentant l''héroïne de Shakespeare flottant dans un ruisseau.'),
('art', 3, 'Quel artiste a créé les colonnes rayées du Palais-Royal à Paris ?', 'Daniel Buren', ARRAY['Jean-Pierre Raynaud', 'Christian Boltanski', 'Annette Messager'], 'fr', true, 'Daniel Buren a installé "Les Deux Plateaux" en 1986, 260 colonnes rayées noir et blanc dans la cour du Palais-Royal.'),
('art', 3, 'Comment appelle-t-on un portrait représentant l''artiste lui-même ?', 'Un autoportrait', ARRAY['Un portrait de commande', 'Un portrait de groupe', 'Un portrait d''apparat'], 'fr', true, 'L''autoportrait est un genre où l''artiste se représente lui-même, pratiqué depuis la Renaissance par de nombreux peintres.'),
('art', 3, 'Quel style architectural est caractérisé par des formes géométriques et des zigzags ?', 'L''Art déco', ARRAY['L''Art nouveau', 'Le Bauhaus', 'Le Modernisme'], 'fr', true, 'L''Art déco, né dans les années 1920, se distingue par ses formes géométriques, ses lignes droites et ses motifs stylisés.'),
('art', 3, 'Quel peintre vénitien est le maître de la couleur au XVIe siècle ?', 'Le Titien', ARRAY['Tintoret', 'Véronèse', 'Giovanni Bellini'], 'fr', true, 'Titien (Tiziano Vecellio) est considéré comme le plus grand coloriste de la Renaissance vénitienne.'),
('art', 3, 'Quel artiste contemporain est connu pour ses sculptures d''animaux en acier ?', 'Jeff Koons', ARRAY['Damien Hirst', 'Takashi Murakami', 'Ai Weiwei'], 'fr', true, 'Jeff Koons est célèbre pour ses Balloon Dogs et autres sculptures d''animaux en acier inoxydable poli miroir.'),
('art', 3, 'Quel est le terme désignant une peinture à quatre panneaux ?', 'Un polyptyque', ARRAY['Un diptyque', 'Un triptyque', 'Un retable'], 'fr', true, 'Un polyptyque est une peinture composée de plusieurs panneaux articulés, souvent utilisé dans l''art religieux.'),
('art', 3, 'Quel peintre baroque est connu pour ses natures mortes de vanités ?', 'Philippe de Champaigne', ARRAY['Georges de La Tour', 'Nicolas Poussin', 'Charles Le Brun'], 'fr', true, 'Philippe de Champaigne a peint des vanités célèbres, symbolisant la fragilité de la vie avec des crânes et des sabliers.'),
('art', 3, 'Quel architecte a conçu le Centre Pompidou à Paris ?', 'Renzo Piano et Richard Rogers', ARRAY['Jean Nouvel et Frank Gehry', 'Norman Foster et Zaha Hadid', 'Le Corbusier et Oscar Niemeyer'], 'fr', true, 'Piano et Rogers ont conçu ce bâtiment révolutionnaire inauguré en 1977, avec ses structures colorées apparentes.'),
('art', 3, 'Quel artiste surréaliste belge a peint "Le Fils de l''homme" ?', 'René Magritte', ARRAY['Paul Delvaux', 'Max Ernst', 'Salvador Dalí'], 'fr', true, 'Magritte a peint Le Fils de l''homme en 1964, un autoportrait où une pomme verte masque le visage.'),
('art', 3, 'Quel est le nom de la technique d''impression à plat sur pierre calcaire ?', 'La lithographie', ARRAY['La sérigraphie', 'L''eau-forte', 'La xylographie'], 'fr', true, 'La lithographie, inventée en 1796, utilise le principe de répulsion entre l''eau et le gras sur une pierre calcaire.'),
('art', 3, 'Quel peintre espagnol a créé la série des "Peintures noires" ?', 'Francisco Goya', ARRAY['Diego Velázquez', 'El Greco', 'José de Ribera'], 'fr', true, 'Goya a peint ses Peintures noires entre 1819 et 1823 sur les murs de sa maison, dont le célèbre "Saturne dévorant un de ses fils".'),
('art', 3, 'Quel mouvement artistique prône le "retour à l''ordre" après la Première Guerre mondiale ?', 'Le Néoclassicisme des années 1920', ARRAY['Le Purisme', 'Le Retour à l''ordre', 'Le Réalisme magique'], 'fr', true, 'Après 1918, de nombreux artistes sont revenus à des formes classiques, rejetant les avant-gardes d''avant-guerre.'),
('art', 3, 'Quel artiste français a créé la fontaine Stravinsky à Paris ?', 'Jean Tinguely et Niki de Saint Phalle', ARRAY['César et Arman', 'Daniel Buren et Christian Boltanski', 'Pierre Soulages et Hans Hartung'], 'fr', true, 'Tinguely et Niki de Saint Phalle ont créé cette fontaine colorée en 1983, près du Centre Pompidou.'),
('art', 3, 'Quel peintre anglais est considéré comme un précurseur de l''impressionnisme pour ses ciels ?', 'William Turner', ARRAY['John Constable', 'Thomas Gainsborough', 'Joshua Reynolds'], 'fr', true, 'Turner est célèbre pour ses paysages lumineux et ses représentations atmosphériques qui ont influencé les impressionnistes.'),
('art', 3, 'Quel artiste est connu pour avoir peint des bottes de foin dans différentes lumières ?', 'Claude Monet', ARRAY['Camille Pissarro', 'Alfred Sisley', 'Jean-François Millet'], 'fr', true, 'Monet a peint la série des Meules entre 1890 et 1891, étudiant les variations de lumière selon les heures et les saisons.'),
('art', 3, 'Quel est le nom du mouvement artistique initié par Pierre Soulages ?', 'L''Outrenoir', ARRAY['L''Art informel', 'Le Tachisme', 'L''Abstraction lyrique'], 'fr', true, 'Soulages a inventé le concept d''Outrenoir, où le noir reflète la lumière plutôt que de l''absorber.'),
('art', 3, 'Quel peintre réaliste français a peint "Un enterrement à Ornans" ?', 'Gustave Courbet', ARRAY['Jean-François Millet', 'Honoré Daumier', 'Rosa Bonheur'], 'fr', true, 'Courbet a peint cet immense tableau en 1849-1850, montrant un enterrement de province à taille réelle, scandalisant les critiques.'),
('art', 3, 'Quel photographe français est connu pour ses portraits en noir et blanc ?', 'Henri Cartier-Bresson', ARRAY['Robert Doisneau', 'Brassaï', 'Willy Ronis'], 'fr', true, 'Cartier-Bresson est considéré comme le père du photojournalisme, inventeur du concept d''instant décisif.'),
('art', 3, 'Quel artiste a créé les "Nymphéas" exposés à l''Orangerie des Tuileries ?', 'Claude Monet', ARRAY['Pierre-Auguste Renoir', 'Edgar Degas', 'Gustave Caillebotte'], 'fr', true, 'Monet a fait don de huit panneaux de Nymphéas à l''État français, installés dans deux salles ovales de l''Orangerie.'),
('art', 3, 'Quel courant artistique des années 1960 utilise des néons et des enseignes lumineuses ?', 'Le Pop Art', ARRAY['Le Minimalisme', 'Le Néo-Dadaïsme', 'Le Nouveau Réalisme'], 'fr', true, 'Le Pop Art s''est emparé de la culture populaire et commerciale, intégrant néons, publicités et objets de consommation.'),
('art', 3, 'Quel artiste a réalisé le "Balloon Dog" en acier inoxydable ?', 'Jeff Koons', ARRAY['Claes Oldenburg', 'Takashi Murakami', 'Damien Hirst'], 'fr', true, 'Jeff Koons a créé ses célèbres Balloon Dogs dans les années 1990, sculptures en acier miroir imitant des ballons de baudruche.'),
('art', 3, 'Quel peintre flamand du XVe siècle a perfectionné la peinture à l''huile ?', 'Jan van Eyck', ARRAY['Robert Campin', 'Rogier van der Weyden', 'Hugo van der Goes'], 'fr', true, 'Jan van Eyck est souvent crédité d''avoir perfectionné la technique de la peinture à l''huile au XVe siècle.'),
('art', 3, 'Quel style architectural caractérise les entrées du métro parisien d''Hector Guimard ?', 'L''Art nouveau', ARRAY['L''Art déco', 'Le Modernisme', 'Le Néoclassique'], 'fr', true, 'Hector Guimard a conçu les édicules du métro parisien en 1900 dans le style Art nouveau, avec des formes végétales en fonte.'),
('art', 3, 'Quel peintre a fondé l''atelier de la Ruche à Paris ?', 'Alfred Boucher', ARRAY['Auguste Rodin', 'Antoine Bourdelle', 'Aristide Maillol'], 'fr', true, 'Le sculpteur Alfred Boucher a fondé La Ruche en 1902, une cité d''artistes à Montparnasse ayant accueilli Chagall, Modigliani et Soutine.'),
('art', 3, 'Quel est le nom de la technique de peinture utilisant de la peinture projetée ?', 'Le dripping', ARRAY['L''action painting', 'Le tachisme', 'Le gestualisme'], 'fr', true, 'Le dripping, popularisé par Jackson Pollock, consiste à faire couler ou projeter la peinture sur la toile posée au sol.'),
('art', 3, 'Quel artiste a peint "Le Bain turc", un tableau circulaire de nus féminins ?', 'Jean-Auguste-Dominique Ingres', ARRAY['Eugène Delacroix', 'Gustave Courbet', 'Alexandre Cabanel'], 'fr', true, 'Ingres a achevé Le Bain turc en 1862, à l''âge de 82 ans, une toile ronde représentant un harem.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('art', 4, 'Quel peintre maniériste florentin a peint "La Déposition de Croix" de Santa Felicita ?', 'Pontormo', ARRAY['Rosso Fiorentino', 'Bronzino', 'Parmigianino'], 'fr', true, 'Pontormo a peint cette Déposition vers 1528, chef-d''œuvre du maniérisme avec ses couleurs acides et ses corps allongés.'),
('art', 4, 'Quel artiste a fondé le groupe CoBrA en 1948 ?', 'Karel Appel', ARRAY['Asger Jorn', 'Pierre Alechinsky', 'Corneille'], 'fr', true, 'CoBrA (Copenhague-Bruxelles-Amsterdam) a été fondé en 1948, prônant une expression artistique spontanée et primitive.'),
('art', 4, 'Quel architecte japonais a conçu le Centre Pompidou-Metz ?', 'Shigeru Ban', ARRAY['Tadao Ando', 'Kengo Kuma', 'Toyo Ito'], 'fr', true, 'Shigeru Ban a conçu ce musée inauguré en 2010, avec sa toiture en bois tressé inspirée d''un chapeau chinois.'),
('art', 4, 'Quel peintre a réalisé les fresques de la chapelle Brancacci à Florence ?', 'Masaccio', ARRAY['Masolino', 'Fra Angelico', 'Filippo Lippi'], 'fr', true, 'Masaccio a peint ces fresques révolutionnaires vers 1425-1427, marquant le début de la Renaissance en peinture.'),
('art', 4, 'Quel artiste est le fondateur du Land Art ?', 'Robert Smithson', ARRAY['Michael Heizer', 'Walter De Maria', 'Richard Long'], 'fr', true, 'Robert Smithson est considéré comme un pionnier du Land Art avec sa Spiral Jetty réalisée en 1970 dans le Grand Lac Salé.'),
('art', 4, 'Quel mouvement artistique est associé à Lucio Fontana et ses toiles lacérées ?', 'Le Spatialisme', ARRAY['L''Art informel', 'Le Nouveau Réalisme', 'L''Arte Povera'], 'fr', true, 'Fontana a fondé le Spatialisme en 1946, créant ses célèbres Concetti spaziali en perçant et lacérant la toile.'),
('art', 4, 'Quel peintre français a théorisé le "Traité de la peinture" au XVIIe siècle ?', 'Nicolas Poussin', ARRAY['Charles Le Brun', 'Philippe de Champaigne', 'Eustache Le Sueur'], 'fr', true, 'Poussin a développé une théorie picturale rigoureuse fondée sur le dessin et l''ordre, influençant l''Académie royale.'),
('art', 4, 'Quel artiste a créé l''installation "The Weather Project" à la Tate Modern ?', 'Olafur Eliasson', ARRAY['James Turrell', 'Anish Kapoor', 'Ai Weiwei'], 'fr', true, 'Eliasson a créé ce soleil artificiel en 2003, transformant le Turbine Hall de la Tate Modern en paysage lumineux.'),
('art', 4, 'Quel peintre vénitien a peint "Les Noces de Cana" exposé au Louvre ?', 'Véronèse', ARRAY['Tintoret', 'Titien', 'Giovanni Bellini'], 'fr', true, 'Véronèse a peint cette toile monumentale en 1563, la plus grande peinture du Louvre avec ses 67 m².'),
('art', 4, 'Quel artiste conceptuel est connu pour son œuvre "One and Three Chairs" ?', 'Joseph Kosuth', ARRAY['Sol LeWitt', 'Lawrence Weiner', 'Robert Barry'], 'fr', true, 'Kosuth a créé cette œuvre en 1965, présentant une chaise réelle, sa photo et sa définition du dictionnaire.'),
('art', 4, 'Quel mouvement artistique est né à Munich en 1911 avec Kandinsky et Marc ?', 'Der Blaue Reiter', ARRAY['Die Brücke', 'Le Bauhaus', 'La Sécession viennoise'], 'fr', true, 'Der Blaue Reiter (Le Cavalier bleu) a été fondé en 1911 par Kandinsky et Franz Marc à Munich.'),
('art', 4, 'Quel artiste a inventé le concept de "sculpture sociale" ?', 'Joseph Beuys', ARRAY['Wolf Vostell', 'Nam June Paik', 'Yoko Ono'], 'fr', true, 'Joseph Beuys a développé le concept de sculpture sociale, affirmant que chaque personne est un artiste capable de transformer la société.'),
('art', 4, 'Quel peintre baroque français est connu pour ses scènes nocturnes éclairées à la bougie ?', 'Georges de La Tour', ARRAY['Louis Le Nain', 'Philippe de Champaigne', 'Nicolas Poussin'], 'fr', true, 'Georges de La Tour est célèbre pour ses scènes nocturnes aux éclairages intimes, comme "Le Tricheur à l''as de carreau".'),
('art', 4, 'Quel artiste chinois contemporain a créé les graines de tournesol en porcelaine à la Tate Modern ?', 'Ai Weiwei', ARRAY['Cai Guo-Qiang', 'Xu Bing', 'Zhang Huan'], 'fr', true, 'Ai Weiwei a créé "Sunflower Seeds" en 2010, composé de 100 millions de graines de tournesol en porcelaine peintes à la main.'),
('art', 4, 'Quel architecte a conçu la Fondation Louis Vuitton à Paris ?', 'Frank Gehry', ARRAY['Jean Nouvel', 'Renzo Piano', 'Tadao Ando'], 'fr', true, 'Frank Gehry a conçu ce bâtiment spectaculaire en forme de voiles de verre, inauguré en 2014 au Bois de Boulogne.'),
('art', 4, 'Quel peintre néoclassique a peint "Le Serment des Horaces" ?', 'Jacques-Louis David', ARRAY['Jean-Auguste-Dominique Ingres', 'Anne-Louis Girodet', 'François Gérard'], 'fr', true, 'David a peint ce tableau en 1784 à Rome, manifeste du néoclassicisme exaltant le patriotisme et le sacrifice.'),
('art', 4, 'Quel est le nom du procédé photographique inventé par Nicéphore Niépce ?', 'L''héliographie', ARRAY['Le daguerréotype', 'Le calotype', 'Le collodion'], 'fr', true, 'Niépce a inventé l''héliographie vers 1826, créant la première photographie permanente de l''histoire.'),
('art', 4, 'Quel artiste a réalisé "La Pietà Rondanini", sa dernière sculpture inachevée ?', 'Michel-Ange', ARRAY['Le Bernin', 'Donatello', 'Antonio Canova'], 'fr', true, 'Michel-Ange a travaillé sur cette Pietà jusqu''à sa mort en 1564, une œuvre brute et émouvante conservée à Milan.'),
('art', 4, 'Quel mouvement est caractérisé par les peintures "all-over" de Pollock ?', 'L''Expressionnisme abstrait', ARRAY['L''Art informel', 'Le Tachisme', 'L''Action painting'], 'fr', true, 'L''Expressionnisme abstrait américain, dont Pollock est le chef de file, se caractérise par des toiles entièrement recouvertes de peinture.'),
('art', 4, 'Quel artiste a peint la série "Les Femmes d''Alger" d''après Delacroix ?', 'Pablo Picasso', ARRAY['Henri Matisse', 'Francis Bacon', 'Willem de Kooning'], 'fr', true, 'Picasso a créé 15 variations des Femmes d''Alger de Delacroix entre 1954 et 1955, chacune devenant plus abstraite.'),
('art', 4, 'Quel sculpteur italien a créé "Forme uniche della continuità nello spazio" ?', 'Umberto Boccioni', ARRAY['Giacomo Balla', 'Carlo Carrà', 'Gino Severini'], 'fr', true, 'Boccioni a créé cette sculpture futuriste en 1913, représentant une figure en mouvement dynamique.'),
('art', 4, 'Quel peintre français a peint "La Tour de Babel" conservée au Kunsthistorisches Museum ?', 'Pieter Bruegel l''Ancien', ARRAY['Jérôme Bosch', 'Albrecht Dürer', 'Lucas van Leyden'], 'fr', true, 'Bruegel l''Ancien a peint cette Tour de Babel vers 1563, un tableau flamand célèbre pour ses détails architecturaux.'),
('art', 4, 'Quel est le courant artistique de Bridget Riley avec ses illusions optiques ?', 'L''Op Art', ARRAY['Le Cinétisme', 'Le Minimalisme', 'L''Art concret'], 'fr', true, 'L''Op Art (art optique) crée des illusions d''optique par des motifs géométriques, et Riley en est une figure majeure.'),
('art', 4, 'Quel artiste a peint "Les Ménines" en version cubiste en 1957 ?', 'Pablo Picasso', ARRAY['Georges Braque', 'Juan Gris', 'Fernand Léger'], 'fr', true, 'Picasso a réalisé 58 variations des Ménines de Velázquez en 1957, explorant la composition sous un angle cubiste.'),
('art', 4, 'Quel photographe américain est connu pour ses paysages d''Ansel Adams ?', 'Ansel Adams', ARRAY['Edward Weston', 'Dorothea Lange', 'Walker Evans'], 'fr', true, 'Ansel Adams est célèbre pour ses photographies en noir et blanc des paysages de l''Ouest américain, notamment Yosemite.'),
('art', 4, 'Quel peintre a peint "Le Vertige" et fait partie de l''École de Paris ?', 'Chaïm Soutine', ARRAY['Amedeo Modigliani', 'Marc Chagall', 'Jules Pascin'], 'fr', true, 'Soutine, peintre lituanien installé à Paris, est connu pour ses paysages tourmentés et ses natures mortes expressives.'),
('art', 4, 'Quel est le nom de la technique de peinture sur bois avec des feuilles d''or ?', 'La dorure', ARRAY['La laque', 'La marqueterie', 'L''intarsia'], 'fr', true, 'La dorure consiste à appliquer des feuilles d''or sur une surface, technique très utilisée dans les retables médiévaux.'),
('art', 4, 'Quel artiste britannique est connu pour ses animaux en formaldéhyde ?', 'Damien Hirst', ARRAY['Tracey Emin', 'Jake Chapman', 'Marc Quinn'], 'fr', true, 'Damien Hirst est célèbre pour ses œuvres avec des animaux dans du formol, comme le requin de "The Physical Impossibility of Death".'),
('art', 4, 'Quel peintre a créé le tableau "Les Glaneuses" représentant des paysannes ?', 'Jean-François Millet', ARRAY['Gustave Courbet', 'Rosa Bonheur', 'Jules Breton'], 'fr', true, 'Millet a peint Les Glaneuses en 1857, montrant trois paysannes ramassant des épis après la moisson.'),
('art', 4, 'Quel artiste est le chef de file du mouvement BMPT dans les années 1960 ?', 'Daniel Buren', ARRAY['Olivier Mosset', 'Michel Parmentier', 'Niele Toroni'], 'fr', true, 'Le groupe BMPT (Buren, Mosset, Parmentier, Toroni) a remis en question les conventions de la peinture dans les années 1960.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('art', 5, 'Quel artiste a théorisé l''"Esthétique relationnelle" dans les années 1990 ?', 'Nicolas Bourriaud', ARRAY['Hans Ulrich Obrist', 'Jérôme Sans', 'Catherine David'], 'fr', true, 'Nicolas Bourriaud a théorisé l''esthétique relationnelle en 1998, définissant un art basé sur les interactions humaines.'),
('art', 5, 'Quel peintre a créé la technique du "sfumato" poussée à l''extrême dans "La Vierge aux rochers" ?', 'Léonard de Vinci', ARRAY['Andrea del Verrocchio', 'Raphaël', 'Le Pérugin'], 'fr', true, 'Léonard a développé le sfumato, une transition imperceptible entre les ombres et les lumières, dans cette œuvre de 1483-1486.'),
('art', 5, 'Quel mouvement est associé à Simon Hantaï et sa technique du "pliage" ?', 'L''Abstraction analytique', ARRAY['Le Supports/Surfaces', 'L''Art informel', 'Le Tachisme'], 'fr', true, 'Hantaï a développé la technique du pliage dès 1960, froissant la toile avant de peindre puis la dépliant.'),
('art', 5, 'Quel peintre allemand de la Renaissance a créé la série "Apocalypse" en gravure sur bois ?', 'Albrecht Dürer', ARRAY['Hans Holbein', 'Lucas Cranach', 'Martin Schongauer'], 'fr', true, 'Dürer a publié sa série de 15 gravures de l''Apocalypse en 1498, révolutionnant l''art de la gravure.'),
('art', 5, 'Quel artiste a créé le concept de "Gesamtkunstwerk" (œuvre d''art totale) en peinture ?', 'Richard Wagner', ARRAY['Vassily Kandinsky', 'Walter Gropius', 'William Morris'], 'fr', true, 'Wagner a théorisé le Gesamtkunstwerk, l''œuvre d''art totale réunissant tous les arts, concept repris par de nombreux artistes.'),
('art', 5, 'Quel est le nom du groupe d''artistes viennois fondé en 1897 autour de Klimt ?', 'La Sécession viennoise', ARRAY['Le Jugendstil', 'Der Blaue Reiter', 'Die Brücke'], 'fr', true, 'La Sécession viennoise a été fondée en 1897 par Gustav Klimt et d''autres artistes en rupture avec l''académisme.'),
('art', 5, 'Quel peintre a réalisé le polyptyque de l''Agneau mystique à Gand ?', 'Jan et Hubert van Eyck', ARRAY['Rogier van der Weyden', 'Hans Memling', 'Robert Campin'], 'fr', true, 'Les frères van Eyck ont achevé ce retable en 1432, chef-d''œuvre des Primitifs flamands composé de 12 panneaux.'),
('art', 5, 'Quel artiste a inventé le terme "Happening" dans les années 1950 ?', 'Allan Kaprow', ARRAY['John Cage', 'Claes Oldenburg', 'Jim Dine'], 'fr', true, 'Allan Kaprow a inventé le terme Happening en 1959 pour décrire ses événements artistiques participatifs et éphémères.'),
('art', 5, 'Quel peintre français a réalisé les décors du plafond de l''Opéra Garnier ?', 'Marc Chagall', ARRAY['André Masson', 'Raoul Dufy', 'Fernand Léger'], 'fr', true, 'Chagall a peint le plafond de l''Opéra Garnier en 1964, à la demande d''André Malraux, représentant des scènes d''opéra et de ballet.'),
('art', 5, 'Quel est le nom du procédé de gravure en relief sur bois ?', 'La xylographie', ARRAY['La chalcographie', 'La taille-douce', 'L''aquatinte'], 'fr', true, 'La xylographie est une technique de gravure en relief sur bois, l''une des plus anciennes méthodes d''impression.'),
('art', 5, 'Quel artiste a créé "Maman", l''araignée géante installée devant la Tate Modern ?', 'Louise Bourgeois', ARRAY['Yayoi Kusama', 'Annette Messager', 'Kiki Smith'], 'fr', true, 'Louise Bourgeois a créé Maman en 1999, une sculpture d''araignée en bronze de 9 mètres, hommage à sa mère tisserande.'),
('art', 5, 'Quel peintre a théorisé la "Section d''Or" avec les frères Duchamp ?', 'Jacques Villon', ARRAY['Albert Gleizes', 'Jean Metzinger', 'Robert Delaunay'], 'fr', true, 'Jacques Villon a organisé l''exposition de la Section d''Or en 1912 avec ses frères Marcel Duchamp et Raymond Duchamp-Villon.'),
('art', 5, 'Quel mouvement né en Italie dans les années 1960 utilise des matériaux pauvres ?', 'L''Arte Povera', ARRAY['Le Nouveau Réalisme', 'L''Art brut', 'Le Postminimalisme'], 'fr', true, 'L''Arte Povera, théorisé par Germano Celant en 1967, utilise des matériaux simples comme la terre, le bois et le tissu.'),
('art', 5, 'Quel peintre a créé le tableau "Composition VIII" en 1923, sommet de son abstraction géométrique ?', 'Vassily Kandinsky', ARRAY['Paul Klee', 'Kasimir Malevitch', 'Piet Mondrian'], 'fr', true, 'Kandinsky a peint Composition VIII en 1923, un chef-d''œuvre d''abstraction géométrique mêlant cercles, lignes et triangles.'),
('art', 5, 'Quel architecte a construit la Villa Savoye à Poissy ?', 'Le Corbusier', ARRAY['Robert Mallet-Stevens', 'Auguste Perret', 'Pierre Chareau'], 'fr', true, 'Le Corbusier a conçu la Villa Savoye en 1929-1931, manifeste des cinq points de l''architecture moderne.'),
('art', 5, 'Quel artiste a peint "Le Grand Verre" pendant huit ans avant de le déclarer inachevé ?', 'Marcel Duchamp', ARRAY['Francis Picabia', 'Man Ray', 'Kurt Schwitters'], 'fr', true, 'Duchamp a travaillé sur "La Mariée mise à nu par ses célibataires, même" de 1915 à 1923 avant de le déclarer définitivement inachevé.'),
('art', 5, 'Quel peintre a créé les "Papiers découpés" dans ses dernières années ?', 'Henri Matisse', ARRAY['Georges Braque', 'Pablo Picasso', 'Joan Miró'], 'fr', true, 'Matisse a développé ses papiers découpés à la fin de sa vie, créant des compositions colorées en découpant des gouaches peintes.'),
('art', 5, 'Quel est le nom du manifeste rédigé par Theo van Doesburg en 1930 sur l''art concret ?', 'Art Concret', ARRAY['De Stijl', 'Cercle et Carré', 'Abstraction-Création'], 'fr', true, 'Van Doesburg a publié le manifeste de l''Art Concret en 1930, prônant un art non figuratif basé sur les mathématiques.'),
('art', 5, 'Quel artiste a réalisé les vitraux de la cathédrale de Metz en 1960 ?', 'Marc Chagall', ARRAY['Henri Matisse', 'Fernand Léger', 'Jean Bazaine'], 'fr', true, 'Chagall a réalisé les vitraux de la cathédrale de Metz entre 1958 et 1968, avec des thèmes bibliques lumineux.'),
('art', 5, 'Quel peintre a inventé le terme "Orphisme" pour décrire ses cercles colorés ?', 'Robert Delaunay', ARRAY['Sonia Delaunay', 'Frantisek Kupka', 'Francis Picabia'], 'fr', true, 'Apollinaire a nommé Orphisme l''art de Delaunay en 1912, caractérisé par des formes circulaires et une abstraction colorée.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('art', 1, 'What color do you get by mixing blue and yellow?', 'Green', ARRAY['Orange', 'Purple', 'Brown'], 'en', true, 'Blue and yellow are primary colors that produce green when mixed together.'),
('art', 1, 'What are the three primary colors in painting?', 'Red, blue, yellow', ARRAY['Red, green, blue', 'Orange, purple, green', 'Black, white, red'], 'en', true, 'In painting, the three primary colors are red, blue, and yellow. All other colors can be created from these.'),
('art', 1, 'What tool does a painter use to mix colors?', 'A palette', ARRAY['An easel', 'A frame', 'A canvas'], 'en', true, 'A palette is a flat surface on which a painter arranges and mixes colors.'),
('art', 1, 'What is a painting of the sea called?', 'A seascape', ARRAY['A portrait', 'A still life', 'A mural'], 'en', true, 'A seascape is a genre of painting that depicts the sea, ships, or coastal views.'),
('art', 1, 'What is the most common surface for painting?', 'Canvas', ARRAY['Paper', 'Wood', 'Glass'], 'en', true, 'Canvas, usually made of linen or cotton, has been the most common painting surface since the Renaissance.'),
('art', 1, 'What do you call a painting of fruits and objects?', 'A still life', ARRAY['A portrait', 'A landscape', 'A mural'], 'en', true, 'A still life is a genre depicting inanimate objects such as fruits, flowers, or household items.'),
('art', 1, 'Which Parisian landmark is a glass pyramid?', 'The Louvre Pyramid', ARRAY['The Eiffel Tower', 'The Arc de Triomphe', 'Sacré-Cœur'], 'en', true, 'The Louvre Pyramid, designed by architect I.M. Pei, was inaugurated in 1989 in the courtyard of the Louvre Museum.'),
('art', 1, 'What color do you get by mixing red and white?', 'Pink', ARRAY['Orange', 'Purple', 'Beige'], 'en', true, 'Adding white to red creates pink, a lighter tint of red.'),
('art', 1, 'What is a painting done directly on a wall called?', 'A fresco', ARRAY['A canvas', 'An engraving', 'A watercolor'], 'en', true, 'A fresco is a wall painting technique where pigments are applied to wet plaster.'),
('art', 1, 'What is the most visited museum in the world?', 'The Louvre', ARRAY['The British Museum', 'The Metropolitan Museum', 'The Musée d''Orsay'], 'en', true, 'The Louvre Museum in Paris welcomes about 10 million visitors per year, making it the most visited museum in the world.'),
('art', 1, 'What color do you get by mixing red and blue?', 'Purple', ARRAY['Green', 'Orange', 'Brown'], 'en', true, 'Red and blue are primary colors that produce purple when mixed together.'),
('art', 1, 'Which Italian artist painted The Last Supper?', 'Leonardo da Vinci', ARRAY['Michelangelo', 'Raphael', 'Botticelli'], 'en', true, 'The Last Supper was painted by Leonardo da Vinci between 1495 and 1498 in Milan.'),
('art', 1, 'What is a quick drawing done freehand called?', 'A sketch', ARRAY['An engraving', 'A lithograph', 'A stained glass'], 'en', true, 'A sketch is a quick freehand drawing that captures the essence of a subject.'),
('art', 1, 'What is the name of the giant statue in New York?', 'The Statue of Liberty', ARRAY['The Thinker', 'David', 'The Colossus of Rhodes'], 'en', true, 'The Statue of Liberty was a gift from France to the United States in 1886, designed by sculptor Bartholdi.'),
('art', 1, 'What material is often used for white sculptures?', 'Marble', ARRAY['Bronze', 'Clay', 'Wood'], 'en', true, 'White marble has been used since antiquity for sculpture, notably by Greek and Roman artists.'),
('art', 1, 'What color do you get by mixing red and yellow?', 'Orange', ARRAY['Green', 'Purple', 'Brown'], 'en', true, 'Mixing red and yellow, two primary colors, produces orange.'),
('art', 1, 'What is a painting of a person''s face called?', 'A portrait', ARRAY['A landscape', 'A still life', 'A seascape'], 'en', true, 'A portrait is a genre focused on representing the appearance of a person, usually their face.'),
('art', 1, 'Which famous white building is in Sydney?', 'The Sydney Opera House', ARRAY['The Taj Mahal', 'The White House', 'The Colosseum'], 'en', true, 'The Sydney Opera House, designed by architect Jørn Utzon, is famous for its distinctive white sail-shaped shells.'),
('art', 1, 'Which painting technique uses water?', 'Watercolor', ARRAY['Oil painting', 'Acrylic', 'Gouache'], 'en', true, 'Watercolor uses pigments diluted in water, producing transparent effects.'),
('art', 1, 'What is the stand called that holds a canvas for painting?', 'An easel', ARRAY['A palette', 'A frame', 'A lectern'], 'en', true, 'An easel is a wooden or metal tripod that holds the canvas while the artist paints.'),
('art', 1, 'Which artist is known for painting water lilies?', 'Claude Monet', ARRAY['Pierre-Auguste Renoir', 'Edgar Degas', 'Paul Cézanne'], 'en', true, 'Claude Monet painted about 250 water lily paintings in his garden at Giverny.'),
('art', 1, 'What color is the sky in most landscape paintings?', 'Blue', ARRAY['Green', 'Red', 'Yellow'], 'en', true, 'The sky is traditionally painted blue, though artists play with different shades depending on the time of day.'),
('art', 1, 'Which Paris museum was formerly a train station?', 'The Musée d''Orsay', ARRAY['The Louvre', 'The Centre Pompidou', 'The Grand Palais'], 'en', true, 'The Musée d''Orsay occupies the former Gare d''Orsay, built in 1900 and converted into a museum in 1986.'),
('art', 1, 'Which artist painted ballet dancers?', 'Edgar Degas', ARRAY['Claude Monet', 'Paul Cézanne', 'Édouard Manet'], 'en', true, 'Edgar Degas is famous for his paintings and pastels of ballet dancers from the Paris Opera.'),
('art', 1, 'What is the art of cutting and gluing paper called?', 'Collage', ARRAY['Engraving', 'Sculpture', 'Molding'], 'en', true, 'Collage is an artistic technique of assembling pieces of paper, fabric, or other materials on a surface.'),
('art', 1, 'What is the complementary color of red?', 'Green', ARRAY['Blue', 'Yellow', 'Orange'], 'en', true, 'On the color wheel, green is the complementary color of red, meaning it is directly opposite.'),
('art', 1, 'Which Spanish artist painted cubist faces?', 'Pablo Picasso', ARRAY['Salvador Dalí', 'Joan Miró', 'Francisco Goya'], 'en', true, 'Pablo Picasso co-founded Cubism, a movement that represents subjects in fragmented geometric forms.'),
('art', 1, 'What is artwork made from small pieces of glass or stone called?', 'A mosaic', ARRAY['A stained glass', 'A fresco', 'A tapestry'], 'en', true, 'A mosaic is a decorative art composed of small colored fragments assembled to form a pattern or image.'),
('art', 1, 'Which country is known for traditional woodblock prints?', 'Japan', ARRAY['China', 'India', 'Korea'], 'en', true, 'Japan is famous for ukiyo-e woodblock prints depicting landscapes, actors, and courtesans.'),
('art', 1, 'What material is used to cast metal statues?', 'Bronze', ARRAY['Gold', 'Silver', 'Iron'], 'en', true, 'Bronze is a copper-tin alloy widely used in sculpture since antiquity for its strength and malleability.'),
('art', 1, 'What is the famous museum in Madrid called?', 'The Prado', ARRAY['The Louvre', 'The Uffizi', 'The Hermitage'], 'en', true, 'The Prado Museum in Madrid houses one of the most important collections of European art from the 12th to 19th centuries.'),
('art', 1, 'What color are the sunflowers Van Gogh painted?', 'Yellow', ARRAY['Red', 'Blue', 'White'], 'en', true, 'Van Gogh''s famous Sunflowers are depicted in various shades of yellow.'),
('art', 1, 'What is a colored glass window in a church called?', 'Stained glass', ARRAY['A fresco', 'A mosaic', 'A relief'], 'en', true, 'Stained glass windows are made of colored glass pieces joined with lead, typical of cathedral architecture.'),
('art', 1, 'What type of art can be seen in the Lascaux caves?', 'Cave paintings', ARRAY['Greek sculpture', 'Roman mosaics', 'Gothic art'], 'en', true, 'The Lascaux caves contain cave paintings dating back about 17,000 years, depicting animals and hunting scenes.'),
('art', 1, 'Who designed the Eiffel Tower?', 'Gustave Eiffel', ARRAY['Le Corbusier', 'Haussmann', 'Auguste Bartholdi'], 'en', true, 'The Eiffel Tower was designed by Gustave Eiffel and built for the 1889 World''s Fair in Paris.'),
('art', 1, 'Which art form uses clay?', 'Pottery', ARRAY['Engraving', 'Lithography', 'Weaving'], 'en', true, 'Pottery is the art of making objects from clay that is shaped and then fired in a kiln.'),
('art', 1, 'Which artist painted Campbell''s soup cans?', 'Andy Warhol', ARRAY['Roy Lichtenstein', 'Keith Haring', 'Jean-Michel Basquiat'], 'en', true, 'Andy Warhol created his famous series of 32 Campbell''s soup can paintings in 1962, becoming a Pop Art icon.'),
('art', 1, 'What is a 3D representation of a person called?', 'A sculpture', ARRAY['A painting', 'A drawing', 'An engraving'], 'en', true, 'Sculpture is the art of shaping or carving material to create a three-dimensional form.'),
('art', 1, 'Which pencil is used for black and white drawing?', 'Graphite pencil', ARRAY['Colored pencil', 'Pastel', 'Charcoal'], 'en', true, 'The graphite pencil is the basic tool for black and white drawing.'),
('art', 1, 'In which country is the Sagrada Familia cathedral?', 'Spain', ARRAY['Italy', 'Portugal', 'France'], 'en', true, 'The Sagrada Familia is a basilica designed by architect Antoni Gaudí in Barcelona, Spain.'),
('art', 1, 'Which French painter is known for Parisian nightlife scenes?', 'Henri de Toulouse-Lautrec', ARRAY['Claude Monet', 'Paul Cézanne', 'Gustave Courbet'], 'en', true, 'Toulouse-Lautrec is famous for his posters and paintings of the nightlife in Montmartre, Paris.'),
('art', 1, 'What is a printed image from an engraved plate called?', 'A print', ARRAY['A watercolor', 'A pastel', 'A wash'], 'en', true, 'A print is an image created by transferring ink from an engraved plate of metal, wood, or stone.'),
('art', 1, 'Which country does origami come from?', 'Japan', ARRAY['China', 'Korea', 'India'], 'en', true, 'Origami is the traditional Japanese art of paper folding to create decorative shapes.'),
('art', 1, 'What is the famous modern art museum in Paris called?', 'The Centre Pompidou', ARRAY['The Louvre', 'The Musée d''Orsay', 'The Petit Palais'], 'en', true, 'The Centre Pompidou, also called Beaubourg, is a modern and contemporary art museum opened in 1977 in Paris.'),
('art', 1, 'Which color often symbolizes nature and hope?', 'Green', ARRAY['Red', 'Blue', 'Yellow'], 'en', true, 'Green is universally associated with nature, growth, and hope.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('art', 2, 'Which Impressionist painter created the Rouen Cathedral series?', 'Claude Monet', ARRAY['Camille Pissarro', 'Alfred Sisley', 'Pierre-Auguste Renoir'], 'en', true, 'Monet painted over 30 views of the Rouen Cathedral between 1892 and 1894, capturing light variations.'),
('art', 2, 'Which architect designed the Notre-Dame-du-Haut chapel in Ronchamp?', 'Le Corbusier', ARRAY['Frank Lloyd Wright', 'Oscar Niemeyer', 'Tadao Ando'], 'en', true, 'Le Corbusier designed this concrete chapel inaugurated in 1955, a masterpiece of modern architecture.'),
('art', 2, 'Which art movement is associated with Henri Matisse?', 'Fauvism', ARRAY['Impressionism', 'Cubism', 'Expressionism'], 'en', true, 'Henri Matisse is the leading figure of Fauvism, a movement characterized by vivid and bold colors.'),
('art', 2, 'What painting technique uses pigments mixed with egg?', 'Tempera', ARRAY['Watercolor', 'Gouache', 'Encaustic'], 'en', true, 'Tempera uses egg yolk as a binder for pigments. It was widely used before the invention of oil painting.'),
('art', 2, 'Which painter created "Dance at Le Moulin de la Galette"?', 'Pierre-Auguste Renoir', ARRAY['Édouard Manet', 'Claude Monet', 'Edgar Degas'], 'en', true, 'Renoir painted this outdoor dance scene at Montmartre in 1876, a masterpiece of Impressionism.'),
('art', 2, 'Which architectural style features pointed arches and stained glass?', 'Gothic', ARRAY['Romanesque', 'Baroque', 'Classical'], 'en', true, 'Gothic architecture is distinguished by pointed arches, ribbed vaults, and large stained glass windows.'),
('art', 2, 'Who painted "Sunflowers", a famous series of still lifes?', 'Vincent van Gogh', ARRAY['Paul Gauguin', 'Claude Monet', 'Paul Cézanne'], 'en', true, 'Van Gogh painted several versions of sunflowers between 1888 and 1889, mostly in Arles.'),
('art', 2, 'What art movement uses small dots of color placed side by side?', 'Pointillism', ARRAY['Impressionism', 'Divisionism', 'Fauvism'], 'en', true, 'Pointillism, developed by Seurat and Signac, uses small dots of pure color placed side by side to create an image.'),
('art', 2, 'Which French sculptor created "The Burghers of Calais"?', 'Auguste Rodin', ARRAY['Camille Claudel', 'Antoine Bourdelle', 'Aristide Maillol'], 'en', true, 'Auguste Rodin created this sculptural group between 1884 and 1889, commemorating an episode of the Hundred Years'' War.'),
('art', 2, 'Which Pop Art artist is known for enlarged comic strips?', 'Roy Lichtenstein', ARRAY['Andy Warhol', 'Jasper Johns', 'Robert Rauschenberg'], 'en', true, 'Roy Lichtenstein adapted the comic book style by enlarging panels with Ben-Day dots.'),
('art', 2, 'Which London museum houses the Tate modern art collection?', 'Tate Modern', ARRAY['British Museum', 'National Gallery', 'Victoria and Albert Museum'], 'en', true, 'Tate Modern, housed in a former power station, is the most visited modern art museum in the world.'),
('art', 2, 'Which artist is the main figure of the De Stijl art movement?', 'Piet Mondrian', ARRAY['Wassily Kandinsky', 'Kazimir Malevich', 'Paul Klee'], 'en', true, 'Mondrian is the main representative of De Stijl, a Dutch movement founded in 1917 promoting geometric abstraction.'),
('art', 2, 'Which Dutch painter is known for intimate genre scenes?', 'Johannes Vermeer', ARRAY['Rembrandt', 'Frans Hals', 'Jan Steen'], 'en', true, 'Vermeer is famous for interior scenes bathed in soft light, such as "The Milkmaid" and "Girl with a Pearl Earring".'),
('art', 2, 'Which sculptor created the Venus de Milo?', 'Alexandros of Antioch', ARRAY['Phidias', 'Praxiteles', 'Polyclitus'], 'en', true, 'The Venus de Milo, sculpted around 100 BC, is attributed to Alexandros of Antioch and is displayed at the Louvre.'),
('art', 2, 'Which artistic movement was born in Italy in the 15th century?', 'The Renaissance', ARRAY['The Baroque', 'Mannerism', 'Gothic'], 'en', true, 'The Renaissance was born in Florence in the 15th century, marking an artistic and intellectual renewal in Europe.'),
('art', 2, 'Which painter is known for paintings of Mont Sainte-Victoire?', 'Paul Cézanne', ARRAY['Claude Monet', 'Camille Pissarro', 'Alfred Sisley'], 'en', true, 'Paul Cézanne painted Mont Sainte-Victoire in Provence more than 80 times, a symbol of his attachment to the region.'),
('art', 2, 'Which Belgian artist painted "The Treachery of Images" with a pipe?', 'René Magritte', ARRAY['Paul Delvaux', 'James Ensor', 'Fernand Khnopff'], 'en', true, 'Magritte painted this surrealist work in 1929, with the inscription "This is not a pipe" below the image of a pipe.'),
('art', 2, 'What is the architectural style of the Palace of Versailles?', 'Classicism', ARRAY['Baroque', 'Gothic', 'Romanesque'], 'en', true, 'The Palace of Versailles is a masterpiece of French classical architecture from the 17th century.'),
('art', 2, 'Which painter created "Impression, Sunrise"?', 'Claude Monet', ARRAY['Édouard Manet', 'Pierre-Auguste Renoir', 'Camille Pissarro'], 'en', true, 'This 1872 painting gave its name to the Impressionist movement at the 1874 exhibition.'),
('art', 2, 'Which artist is known for silk-screen prints of Marilyn Monroe?', 'Andy Warhol', ARRAY['Roy Lichtenstein', 'Keith Haring', 'Jean-Michel Basquiat'], 'en', true, 'Andy Warhol created his famous Marilyn Monroe silk-screen series in 1962, after the actress''s death.'),
('art', 2, 'What decorative art is made of interlaced threads?', 'Tapestry', ARRAY['Mosaic', 'Stained glass', 'Ceramics'], 'en', true, 'Tapestry is a textile art where colored threads are woven to create patterns and scenes.'),
('art', 2, 'Which German Romantic painter created "Wanderer Above the Sea of Fog"?', 'Caspar David Friedrich', ARRAY['Philipp Otto Runge', 'Carl Spitzweg', 'Arnold Böcklin'], 'en', true, 'Friedrich painted this emblematic Romantic work around 1818, showing a man facing sublime nature.'),
('art', 2, 'Which Mexican artist is known for colorful self-portraits?', 'Frida Kahlo', ARRAY['Diego Rivera', 'Remedios Varo', 'Leonora Carrington'], 'en', true, 'Frida Kahlo painted over 55 self-portraits expressing her physical and emotional pain with a unique style.'),
('art', 2, 'Which white marble Indian monument is considered an architectural masterpiece?', 'The Taj Mahal', ARRAY['The Red Fort', 'The Lotus Temple', 'The Palace of the Winds'], 'en', true, 'The Taj Mahal in Agra, built in the 17th century, is a white marble mausoleum built by Emperor Shah Jahan.'),
('art', 2, 'Which painter founded Suprematism?', 'Kazimir Malevich', ARRAY['Wassily Kandinsky', 'El Lissitzky', 'Alexander Rodchenko'], 'en', true, 'Malevich founded Suprematism in 1915, an abstract art movement based on simple geometric forms.'),
('art', 2, 'Which artist created the colorful "Nanas" sculptures?', 'Niki de Saint Phalle', ARRAY['Louise Bourgeois', 'Yayoi Kusama', 'Barbara Hepworth'], 'en', true, 'Niki de Saint Phalle is famous for her Nanas, monumental colorful female sculptures created in the 1960s.'),
('art', 2, 'Which American painter is known for his painting "Nighthawks"?', 'Edward Hopper', ARRAY['Norman Rockwell', 'Grant Wood', 'Andrew Wyeth'], 'en', true, 'Edward Hopper painted Nighthawks in 1942, depicting customers in a late-night diner, a symbol of urban loneliness.'),
